/**
 * Generate FlightAPI firewall config.
 *
 * Data source: https://docs.flightapi.io
 *
 * FlightAPI embeds the API key as a path segment:
 *   `https://api.flightapi.io/{endpoint}/$FLIGHTAPI_TOKEN/...`
 *
 * The firewall accepts requests with the token in the path and rewrites
 * via the Bearer header so the proxy can substitute the secret at runtime.
 */

import { writeOutput } from "./codegen";

const DOCS_URL = "https://docs.flightapi.io";
const PLACEHOLDER_VALUE = "c0ffeesafelocal5afe10ca1";

function generateTypeScript(): string {
  const lines: string[] = [
    "// Auto-generated from FlightAPI API docs.",
    `// Source: ${DOCS_URL}`,
    "// Regenerate: cd turbo && pnpm -F @vm0/firewalls-generator generate:flightapi",
    "//",
    "// DO NOT EDIT THIS FILE MANUALLY.",
    "",
    'import type { FirewallConfig } from "../firewall-types";',
    "",
    "export const flightapiFirewall = {",
    '  name: "flightapi",',
    '  description: "FlightAPI",',
    "  placeholders: {",
    `    FLIGHTAPI_TOKEN: "${PLACEHOLDER_VALUE}",`,
    "  },",
    "  apis: [",
    "    {",
    '      base: "https://api.flightapi.io",',
    "      auth: {",
    "        headers: {",
    '          Authorization: "Bearer ${{ secrets.FLIGHTAPI_TOKEN }}",',
    "        },",
    "      },",
    "      permissions: [],",
    "    },",
    "  ],",
    "} as const satisfies FirewallConfig;",
    "",
  ];
  return lines.join("\n");
}

export async function generate(): Promise<void> {
  console.error("Generating FlightAPI firewall config...");
  const ts = generateTypeScript();
  writeOutput("flightapi", ts, import.meta.dirname);
}
